window.products.push({"id":1136471,"name":"Walt Disney Classics Collection (WDCC) Jiminy Cricket, 1993 Charter Membership Figurine","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/61+2hK0jTtL._AC_SL1500_.jpg","description":"Walt Disney's Classics Collection Presents: \"Cricket's the name- Jiminy Cricket\" From Pinocchio. This piece is in Mint condition and comes in it's original box, complete with COA. Title: Cricket's the name- Jiminy Cricket Character: Jiminy Cricket from Pinocchio Sculptor: Kent Melton Year of Issue:1992 Retired: December of 1993 This also includes a Walt Disney Jiminy Cricket Collector's Society Charter Member Pin, brand new! This is the first Membership Gift sculpture of the Walt Disney Classics Collection, the so called Charter Membership.. The Walt Disney Classics Collection uses an annual production mark to recognize major chronological milestones of Disney animation history. The production mark which is beneath this piece is, 1992 Steamboat wheel from Steamboat Willie (1928)","images":["https://m.media-amazon.com/images/I/61+2hK0jTtL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Walt Disney Classics Collection","source_asin":"B001O6YB7C","category_path":"Home & Kitchen"},"sku":"BM-1136471","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B001O6YB7C","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B001O6YB7C","price_pending":true,"merchant_ready":false});
